import { test } from "node:test";
import assert from "node:assert/strict";
import { loadConfig } from "./config.js";

const base = {
  SLACK_BOT_TOKEN: "xoxb",
  SLACK_APP_TOKEN: "xapp",
  SPACE_API_URL: "http://localhost:8080",
  SPACE_DATA_PLANE_URL: "http://localhost:8090",
  SPACE_API_TOKEN: "t",
  INFISICAL_UNIVERSAL_AUTH_CLIENT_ID: "id",
  INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET: "secret",
  AGENT_VAULT_ACCESS_BUNDLE: "coding-agent",
  AGENT_VAULT_PROXY_ADDRESS: "10.0.0.5:17323",
  AGENT_VAULT_CA_FINGERPRINT: "SHA256:AA:BB",
};

test("defaults for everything optional", () => {
  const config = loadConfig(base);
  assert.equal(config.space.template, "coding-agent:v1");
  assert.equal(config.vault.domain, "https://app.infisical.com");
  assert.equal(config.maxSandboxes, 3);
  assert.equal(config.runTimeoutMs, 600_000);
  assert.equal(config.stateDir, "state");
  assert.deepEqual(config.space.networkPolicy.egress.allow, [{ ip: "10.0.0.5" }], "sandboxes may reach only the proxy");
});

test("lists every missing variable at once", () => {
  assert.throws(() => loadConfig({}), /SLACK_BOT_TOKEN, SLACK_APP_TOKEN, SPACE_API_URL.*AGENT_VAULT_PROXY_ADDRESS/);
});

test("slack: false skips the Slack variables and the CA pin, for the smoke test", () => {
  const { SLACK_BOT_TOKEN, SLACK_APP_TOKEN, AGENT_VAULT_CA_FINGERPRINT, ...rest } = base;
  assert.doesNotThrow(() => loadConfig(rest, { slack: false }));
});

test("the bot refuses to start without a pinned proxy CA", () => {
  const { AGENT_VAULT_CA_FINGERPRINT, ...rest } = base;
  assert.throws(() => loadConfig(rest), /Missing required environment variables: AGENT_VAULT_CA_FINGERPRINT/);
});

test("rejects a non-numeric limit", () => {
  assert.throws(() => loadConfig({ ...base, MAX_SANDBOXES: "many" }), /MAX_SANDBOXES must be a positive integer/);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { createLineSplitter, parseSse } from "./sse.js";
import { collect } from "./test-helpers/fakes.js";

async function* chunks(...parts: string[]) {
  const encoder = new TextEncoder();
  for (const part of parts) yield encoder.encode(part);
}

test("line splitter: joins lines split across chunks and handles CRLF split between chunks", () => {
  const lines = createLineSplitter();
  assert.deepEqual(lines.push('{"a":'), []);
  assert.deepEqual(lines.push('1}\n{"b"'), ['{"a":1}']);
  assert.deepEqual(lines.push(":2}\r"), []);
  assert.deepEqual(lines.push("\nlast"), ['{"b":2}']);
  assert.deepEqual(lines.end(), ["last"]);
  assert.deepEqual(lines.end(), []);
});

test("parseSse: named events, multi-line data, ids and comments", async () => {
  const events = await collect(
    parseSse(chunks(": keepalive\n", "event: stdout\nid: 1\ndata: hel", "lo\ndata: world\n\n", "data:x\n\n")),
  );
  assert.deepEqual(events, [
    { event: "stdout", data: "hello\nworld", id: "1" },
    { event: "message", data: "x", id: "1" },
  ]);
});

test("parseSse: a multi-byte character split across chunks decodes intact", async () => {
  const bytes = new TextEncoder().encode("data: é\n\n");
  async function* split() {
    yield bytes.slice(0, 7);
    yield bytes.slice(7);
  }
  assert.deepEqual(await collect(parseSse(split())), [{ event: "message", data: "é" }]);
});

test("parseSse: drops an event cut off before its blank line", async () => {
  assert.deepEqual(await collect(parseSse(chunks("data: done\n\n", "data: cut"))), [{ event: "message", data: "done" }]);
});

test("line splitter: a line past the limit throws instead of growing without end", () => {
  const lines = createLineSplitter(8);
  assert.deepEqual(lines.push("12345678\n1234"), ["12345678"]);
  assert.throws(() => lines.push("56789"), /output line over 8 characters/);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createJournal, loadInstanceId } from "./journal.js";
import { tempDir as makeTempDir } from "./test-helpers/fakes.js";

const tempDir = () => makeTempDir("journal-");

test("write, update, list and remove a record", () => {
  const dir = tempDir();
  const journal = createJournal(dir, () => {});
  journal.write({ runId: "r1", startedAt: "t", sessionId: "s1" });
  journal.write({ runId: "r1", startedAt: "t", sessionId: "s1", sandboxId: "b1" });
  assert.deepEqual(journal.list(), [{ runId: "r1", startedAt: "t", sessionId: "s1", sandboxId: "b1" }]);
  // The temp file is renamed away, never left beside the record.
  assert.deepEqual(readdirSync(dir), ["r1.json"]);
  journal.remove("r1");
  assert.deepEqual(journal.list(), []);
});

test("list survives a new journal on the same directory, as after a restart", () => {
  const dir = tempDir();
  createJournal(dir).write({ runId: "r1", startedAt: "t", sandboxId: "b1" });
  assert.deepEqual(createJournal(dir).list(), [{ runId: "r1", startedAt: "t", sandboxId: "b1" }]);
});

test("list skips unreadable files and leftover temp files", () => {
  const dir = tempDir();
  const logs: string[] = [];
  writeFileSync(join(dir, "bad.json"), "{");
  writeFileSync(join(dir, "r2.json.tmp"), "{}");
  assert.deepEqual(createJournal(dir, (m) => logs.push(m)).list(), []);
  assert.match(logs[0], /bad\.json/);
});

test("remove of a missing record is a no-op", () => {
  assert.doesNotThrow(() => createJournal(tempDir()).remove("nope"));
});

test("loadInstanceId: made once, then the same after a restart; another directory gets its own", () => {
  const dir = tempDir();
  const id = loadInstanceId(dir);
  assert.equal(loadInstanceId(dir), id);
  assert.notEqual(loadInstanceId(join(dir, "smoke")), id);
  assert.ok(createJournal(dir).list().length === 0, "the ID file isn't read as a run record");
});

