import { test } from "node:test";
import assert from "node:assert/strict";
import { EMAIL_CACHE_MS, createAccessCheck, memberEmail, parseAllowlist } from "./access.js";

test("memberEmail: only a live human from the home team or org counts", () => {
  const profile = { email: "alex@example.com" };
  const home = { teamId: "T1", enterpriseId: "E1" };
  assert.equal(memberEmail({ team_id: "T1", profile }, home), "alex@example.com");
  assert.equal(memberEmail({ team_id: "T2", enterprise_user: { enterprise_id: "E1" }, profile }, home), "alex@example.com");
  // A Slack Connect user from another org, whose admin chose the email.
  assert.equal(memberEmail({ team_id: "T9", enterprise_user: { enterprise_id: "E9" }, profile }, home), undefined);
  assert.equal(memberEmail({ team_id: "T9", profile }, { teamId: "T1" }), undefined);
  assert.equal(memberEmail({ team_id: "T1", deleted: true, profile }, home), undefined);
  assert.equal(memberEmail({ team_id: "T1", is_bot: true, profile }, home), undefined);
  assert.equal(memberEmail(undefined, home), undefined);
  // An unknown home never matches a user with no team.
  assert.equal(memberEmail({ profile }, {}), undefined);
});

test("a cached email expires, so a changed email loses access", async () => {
  let t = 0;
  let email = "alex@example.com";
  const isAllowed = createAccessCheck({
    allowlist: parseAllowlist("alex@example.com"),
    lookupEmail: async () => email,
    now: () => t,
  });
  assert.equal(await isAllowed("U9"), true);
  email = "other@example.com";
  t = EMAIL_CACHE_MS - 1;
  assert.equal(await isAllowed("U9"), true);
  t = EMAIL_CACHE_MS;
  assert.equal(await isAllowed("U9"), false);
});

test("parseAllowlist: splits on commas and whitespace, sorting IDs from emails", () => {
  const { userIds, emails } = parseAllowlist(" U1, u2\nAlex@Example.com ,, ");
  assert.deepEqual([...userIds], ["U1", "U2"]);
  assert.deepEqual([...emails], ["alex@example.com"]);
});

test("allows a listed user ID without looking up an email", async () => {
  const lookups: string[] = [];
  const isAllowed = createAccessCheck({
    allowlist: parseAllowlist("U1, alex@example.com"),
    lookupEmail: async (id) => (lookups.push(id), undefined),
  });
  assert.equal(await isAllowed("U1"), true);
  assert.deepEqual(lookups, []);
});

test("allows a user whose email is listed, case-insensitively, and caches the lookup", async () => {
  const lookups: string[] = [];
  const isAllowed = createAccessCheck({
    allowlist: parseAllowlist("alex@example.com"),
    lookupEmail: async (id) => (lookups.push(id), "Alex@Example.com"),
  });
  assert.equal(await isAllowed("U9"), true);
  assert.equal(await isAllowed("U9"), true);
  assert.deepEqual(lookups, ["U9"]);
});

test("skips the lookup when the list has no emails", async () => {
  const isAllowed = createAccessCheck({
    allowlist: parseAllowlist("U1"),
    lookupEmail: async () => assert.fail("should not look up"),
  });
  assert.equal(await isAllowed("U2"), false);
});

test("fails closed: empty list, missing user, no email, failed lookup", async () => {
  const log = () => {};
  assert.equal(await createAccessCheck({ allowlist: parseAllowlist(""), lookupEmail: async () => "a@b.c", log })("U1"), false);

  const listed = parseAllowlist("a@b.c");
  assert.equal(await createAccessCheck({ allowlist: listed, lookupEmail: async () => "a@b.c", log })(undefined), false);
  assert.equal(await createAccessCheck({ allowlist: listed, lookupEmail: async () => undefined, log })("U1"), false);

  // A failed lookup isn't cached, so the next message retries.
  let calls = 0;
  const flaky = createAccessCheck({
    allowlist: listed,
    lookupEmail: async () => {
      if (++calls === 1) throw new Error("ratelimited");
      return "a@b.c";
    },
    log,
  });
  assert.equal(await flaky("U1"), false);
  assert.equal(await flaky("U1"), true);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { createVault } from "./vault.js";

interface Call {
  method: string;
  url: string;
  auth?: string;
  body?: unknown;
}

/** A fetch that records calls and answers from `routes`, keyed by "METHOD path". */
function fakeFetch(routes: Record<string, (call: Call) => { status?: number; body: unknown }>) {
  const calls: Call[] = [];
  const doFetch = (async (url: string, init: RequestInit) => {
    const headers = (init.headers ?? {}) as Record<string, string>;
    const call: Call = {
      method: init.method ?? "GET",
      url,
      auth: headers.authorization,
      body: init.body ? JSON.parse(init.body as string) : undefined,
    };
    calls.push(call);
    const route = routes[`${call.method} ${new URL(url).pathname}`];
    const { status = 200, body } = route ? route(call) : { status: 404, body: { message: "not found" } };
    return new Response(JSON.stringify(body), { status });
  }) as typeof fetch;
  return { calls, doFetch };
}

const LOGIN = "POST /api/v1/auth/universal-auth/login";
const CREATE = "POST /api/v1/agent-vault/sessions";
let logins = 0;
const login = () => ({ body: { accessToken: [REDACTED]}`, expiresIn: 3600, tokenType: "Bearer" } });

function vault(routes: Parameters<typeof fakeFetch>[0]) {
  const { calls, doFetch } = fakeFetch({ [LOGIN]: login, ...routes });
  const v = createVault({
    domain: "https://infisical.test/",
    clientId: "cid",
    clientSecret: "csecret",
    fetch: doFetch,
  });
  return { calls, ...v };
}

const request = (accessBundles = ["coding-agent"], ttl = "15m") => ({ accessBundles, ttl });

test("create: logs in once, then mints a session for the bundle with the ttl", async () => {
  const { calls, sessions } = vault({
    [CREATE]: () => ({ body: { session: { id: "s1", token: "agv_x", expiresAt: null, accessBundles: [] } } }),
  });
  assert.deepEqual(await sessions.create(request()), { id: "s1", token: "agv_x" });
  await sessions.create(request());

  assert.equal(calls.filter((c) => c.url.endsWith("/login")).length, 1, "access token is cached");
  assert.deepEqual(calls[0].body, { clientId: "cid", clientSecret: "csecret" });
  assert.equal(calls[1].url, "https://infisical.test/api/v1/agent-vault/sessions");
  assert.deepEqual(calls[1].body, { accessBundles: ["coding-agent"], ttl: "15m" });
  assert.match(calls[1].auth ?? "", /^Bearer at-\d+$/);
});

test("create: each session carries the bundles its caller chose, not one fixed on the client", async () => {
  const { calls, sessions } = vault({ [CREATE]: () => ({ body: { session: { id: "s", token: "t" } } }) });
  await sessions.create(request(["coding-agent"]));
  await sessions.create(request(["read-only"], "5m"));
  assert.deepEqual(
    calls.filter((c) => c.url.endsWith("/sessions")).map((c) => c.body),
    [request(["coding-agent"]), request(["read-only"], "5m")],
  );
});

test("create: a bundle the identity isn't granted is refused by Infisical, and no token comes back", async () => {
  const { sessions } = vault({
    [CREATE]: () => ({
      status: 400,
      body: { message: "No access bundle named 'admin' is granted to you. Check the name, or ask an Agent Vault admin to grant it." },
    }),
  });
  await assert.rejects(sessions.create(request(["admin"])), /HTTP 400 .*'admin' is granted to you/);
});

test("revoke: posts to the session's revoke route", async () => {
  const { calls, sessions } = vault({ "POST /api/v1/agent-vault/sessions/s1/revoke": () => ({ body: { session: {} } }) });
  await sessions.revoke("s1");
  assert.equal(calls.at(-1)?.url, "https://infisical.test/api/v1/agent-vault/sessions/s1/revoke");
});

test("getSession: returns the session's status", async () => {
  const session = {
    id: "s1",
    status: "revoked",
    revokedAt: "2026-10-18T00:00:00Z",
    expiresAt: null,
    accessBundles: [{ name: "coding-agent" }],
  };
  const { getSession } = vault({ "GET /api/v1/agent-vault/sessions/s1": () => ({ body: { session } }) });
  assert.deepEqual(await getSession("s1"), session);
});

test("a 401 logs in again once and retries", async () => {
  let attempts = 0;
  const { calls, sessions } = vault({
    [CREATE]: () =>
      ++attempts === 1 ? { status: 401, body: { message: "expired" } } : { body: { session: { id: "s2", token: "t" } } },
  });
  assert.equal((await sessions.create(request())).id, "s2");
  assert.equal(calls.filter((c) => c.url.endsWith("/login")).length, 2);
});

test("errors carry the status and body but never the credentials, and a failed login isn't cached", async () => {
  let fail = true;
  const { calls, sessions } = vault({
    [LOGIN]: () => (fail ? { status: 400, body: { message: "bad secret" } } : login()),
    [CREATE]: () => ({ status: 403, body: { message: "forbidden" } }),
  });
  const errors: string[] = [];
  const failure = (pattern: RegExp) => (err: Error) => (errors.push(err.message), pattern.test(err.message));
  await assert.rejects(sessions.create(request()), failure(/universal-auth\/login failed: HTTP 400 .*bad secret/));
  fail = false;
  await assert.rejects(sessions.create(request()), failure(/agent-vault\/sessions failed: HTTP 403 .*forbidden/));
  assert.equal(calls.filter((c) => c.url.endsWith("/login")).length, 2);
  assert.ok(errors.every((m) => !m.includes("csecret") && !/\bat-\d/.test(m)), "no client secret or access token");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync } from "node:fs";
import { createClaudeHarness } from "./claude.js";
import { createGateway, toIncoming, type SlackEvent } from "./gateway.js";
import { ERROR_REPLY, NOT_ALLOWED_REPLY, THINKING_TEXT } from "./handler.js";
import { createJournal } from "./journal.js";
import {
  claudeOutput,
  claudeResult,
  claudeToolUse,
  FakeSandboxes,
  FakeSessions,
  FakeSlack,
  flush,
  hang,
  tempDir,
} from "./test-helpers/fakes.js";

const BOT = "UBOT";

/** Slack, the handler and the real runner, with Modal and Agent Vault faked. */
function setup({ output, allowed = ["U1"] }: { output?: FakeSandboxes["output"]; allowed?: string[] } = {}) {
  const dir = tempDir("gateway-");
  const logs: string[] = [];
  const slack = new FakeSlack();
  const sandboxes = new FakeSandboxes(output ?? (() => claudeOutput([claudeToolUse, claudeResult("Here you go.")])));
  const sessions = new FakeSessions();
  const journal = createJournal(dir, (m) => logs.push(m));
  const gateway = createGateway({
    slack,
    isAllowed: async (user) => user !== undefined && allowed.includes(user),
    accessBundles: ["apollo"],
    progressIntervalMs: 0,
    botUserId: BOT,
    sandboxes,
    sessions,
    journal,
    harness: createClaudeHarness({ template: "builtin" }),
    instructions: "Be brief.",
    proxyAddress: "10.0.0.5:17323",
    caFingerprint: "SHA256:AA:BB",
    maxSandboxes: 3,
    timeoutMs: 60_000,
    retryDelayMs: 0,
    replyGraceMs: 1000,
    log: (m) => logs.push(m),
  });
  /** Nothing left behind: every session revoked, every sandbox deleted, no run records. */
  const assertCleanedUp = () => {
    assert.equal(sessions.active.size, 0, "sessions left active");
    assert.equal(sandboxes.live.size, 0, "sandboxes left running");
    assert.deepEqual(readdirSync(dir), [], "run records left in the journal");
  };
  return { logs, slack, sandboxes, sessions, journal, gateway, assertCleanedUp };
}

const dm = (text: string, extra: Partial<SlackEvent> = {}): SlackEvent => ({
  user: "U1",
  text,
  channel: "D1",
  channel_type: "im",
  ts: "100.1",
  ...extra,
});
const channelMessage = (text: string, extra: Partial<SlackEvent> = {}): SlackEvent => ({
  user: "U1",
  text,
  channel: "C1",
  channel_type: "channel",
  ts: "200.1",
  ...extra,
